mapper.select:
SELECT tr.settlement_id AS settlementId, tr.account_id AS accountId, tr.user_id AS userId, tl.travel_id AS travelId, tl.destination, DATE_FORMAT(tl.travel_begin_date, '%Y-%m-%d') AS travelBeginDate, DATE_FORMAT(tl.travel_end_date, '%Y-%m-%d') AS travelEndDate, tr.total_expense AS totalExpense, tr.total_food AS totalFood, tr.total_activity AS totalActivity, tr.total_acc AS totalAcc, tr.total_transport AS totalTransport, tr.total_shop AS totalShop,
/* 계정+기간 한정 최대 지출 제목 */ (SELECT t2.title FROM `transaction` t2 WHERE t2.account_id = tr.account_id AND UPPER(TRIM(t2.transaction_type)) = 'WITHDRAW' AND t2.created_at >= tl.travel_begin_date AND t2.created_at < DATE_ADD(tl.travel_end_date, INTERVAL 1 DAY) ORDER BY t2.amount DESC LIMIT 1) AS maxSpendingTitle,
/* 계정+기간 한정 최대 지출 금액 */ (SELECT t2.amount FROM `transaction` t2 WHERE t2.account_id = tr.account_id AND UPPER(TRIM(t2.transaction_type)) = 'WITHDRAW' AND t2.created_at >= tl.travel_begin_date AND t2.created_at < DATE_ADD(tl.travel_end_date, INTERVAL 1 DAY) ORDER BY t2.amount DESC LIMIT 1) AS maxSpendingAmount
FROM travel_log tl JOIN travel_report tr ON tl.travel_id = tr.travel_id WHERE tl.travel_id = #{travelId}

mapper.insert:
INSERT INTO travel_report (
    account_id, user_id, travel_id,
    total_expense, total_food, total_activity, total_acc, total_transport, total_shop
) VALUES (
             #{param.accountId}, #{param.userId}, #{param.travelId},
             #{param.totalExpense}, #{param.totalFood}, #{param.totalActivity},
             #{param.totalAcc}, #{param.totalTransport}, #{param.totalShop}
         )
